import {objectiveAssessment} from './expedition-book.mjs';import {supplyLedger,SUPPLY_NAMES} from './expedition-settlement.mjs';
// Facts from the selected report only; no reruns, storage reads, or counterfactual claims.
export function objectiveReview(report){const assessment=objectiveAssessment(report);if(!assessment)return null;const m=assessment.metrics,requirements=[{key:'clear',met:m.won&&m.cleared===m.rooms,text:`${['holdout','lockpass'].includes(report.config.expedition)?'完成各房公开条件':'肃清全部房间'}：${m.cleared}/${m.rooms}`,shortfall:m.rooms-m.cleared}],members=report.party.filter(u=>!u.owner&&report.config.heroes.some(h=>h.id===u.id)),down=members.filter(h=>h.hp<=0).map(h=>({id:h.id,name:h.name,eventIndex:report.events.findIndex(e=>e.type==='down'&&e.targets.includes(h.id))})),stop=report.events.findLastIndex(e=>e.type==='defeat'),ledger=supplyLedger(report),resources=[];
 if(assessment.id==='survive')requirements.push({key:'alive',met:m.alive===6,text:`六名队员全部存活：${m.alive}/6`,shortfall:6-m.alive});
 if(assessment.id==='reserve')for(const key of ['rune','arrow']){const row=ledger.rows.find(r=>r.key===key);requirements.push({key,met:m[key]>=2,text:`带回至少2${SUPPLY_NAMES[key]}：实际${m[key]}`,shortfall:Math.max(0,2-m[key])});resources.push({...row,recent:ledger.entries.filter(e=>e.changes.some(c=>c.key===key&&c.delta<0)).slice(-3).map(e=>({eventIndex:report.events.findIndex(x=>x.id===e.eventId),roomIndex:e.roomIndex,round:e.round,spent:-e.changes.find(c=>c.key===key).delta}))});}
 return {...assessment,requirements,down:assessment.id==='survive'?down:[],stopIndex:stop>=0?stop:null,resources};}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function objectiveReviewView(report){const r=objectiveReview(report);if(!r)return '';return `<details class=objective-review ${r.met?'':'open'}><summary>逐项核对${r.met?' · 条件已达成':' · 查看目标缺口'}</summary><ul>${r.requirements.map(q=>`<li data-objective-requirement="${q.key}" data-met="${q.met}">${q.met?'✓':'未满足'} ${esc(q.text)}${q.shortfall?' · 还差'+q.shortfall:''}</li>`).join('')}</ul>${!r.requirements[0].met&&r.stopIndex!==null?`<button data-objective-event="${r.stopIndex}">查看本次止步事件</button>`:''}${r.down.length?'<p>本次倒下的正式队员：</p><div class=bar>'+r.down.map(h=>h.eventIndex>=0?`<button data-objective-event="${h.eventIndex}">查看${esc(h.name)}倒下时的记录</button>`:esc(h.name)).join('')+'</div>':''}${r.resources.map(row=>`<p>${row.name}：携带${row.start}，事件获得${row.gained}，实际支出${row.spent}，结余${row.end}。</p>${row.recent.length?`<details><summary>${row.name}最近${row.recent.length}次实际支出</summary><div class=bar>${row.recent.map(e=>`<button data-objective-event="${e.eventIndex}">第${e.roomIndex+1}房·第${e.round}回合·支出${e.spent}${row.name}</button>`).join('')}</div></details>`:'<p>本次没有这种材料的支出记录。</p>'}`).join('')}<small>这些是已经发生的结果与支出，不证明某次行动多余，也不保证删掉后能达标。可调整频率、媒介、时序或覆盖后重新验证；下一次正式出征使用新编号种子。</small>${!r.met?'<div class=bar><button data-objective-edit>载入本次目标与方案供调整</button></div><small>替换当前准备，可在方案管理撤销；不替换对比方案A。</small>':''}</details>`;}
